 const DR=await api('day_rules?active=eq.true&select=*').catch(()=>[]);let NEWS=NEWS0,cur=NEWS,mode='new',shown=50,rid=0,plan=[],dec=[],pshown=100;const S=Object.fromEntries(sl.map(x=>[x.id,x])),SLV=[...new Set(sl.map(s=>s.level).filter(Boolean))].sort();
