 b.innerHTML=`<div class="card noprint"><h3>اقتراح توزيع الطلاب الجدد</h3><p class="note">يُوزَّع الطلاب غير المسكَّنين على الكلاسات التي بنفس ليفلهم ولم تتجاوز الحد الأقصى (الأقل ازدحاماً أولاً). من لا يجد مكاناً يُترك للتوزيع اليدوي. ويُراعى معيار التوزيع إن حددته بالأسفل.${DR.length?` <b>وتُطبَّق ${DR.length} قاعدة لأيام المستويات الدراسية.</b>`:''}</p><button class="btn" id="sg">اقتراح التوزيع</button></div><div id="sp"></div>
 <details class="card"><summary><b>معايير التوزيع السريع (اختياري)</b></summary><div id="rl"><p class="note">كل معيار: كلية/ليفل الطالب ← اليوم/ليفل الجروب. ليفل الجروب بدون تحديد = نفس ليفل الطالب.</p><div id="rr">${ruleRow()}</div><button type="button" class="btn alt" id="ar">إضافة معيار آخر</button></div></details>
 <div class="card"><div class="msbar"><input id="q" placeholder="بحث بالاسم أو الكود"><label style="margin:0"><input type="checkbox" id="sa"> البحث في كل النظام</label><button class="btn" id="go">بحث</button><button class="btn alt" id="rv">إخفاء الكل (تمت المراجعة)</button></div></div><div id="rs"></div>`;
 initMs($('#rl'));
 const rules=()=>[...document.querySelectorAll('.rr')].map(r=>({c:msVals(r.dataset.i+'c'),l:msVals(r.dataset.i+'l').map(lv),d:msVals(r.dataset.i+'d'),v:msVals(r.dataset.i+'v').map(lv)})).filter(r=>r.c.length||r.l.length||r.d.length||r.v.length);
 const cands=(s,R)=>{const G=new Map();if(!R.length)sl.filter(x=>lv(x.level)==lv(s.level)).forEach(x=>G.set(x.id,x));else R.filter(r=>(!r.c.length||r.c.includes(s.college))&&(!r.l.length||r.l.includes(lv(s.level)))).forEach(r=>sl.filter(x=>(!r.d.length||r.d.includes(x.day))&&(r.v.length?r.v.includes(lv(x.level)):lv(x.level)==lv(s.level))).forEach(x=>G.set(x.id,x)));const al=allowedDays(s,DR);return[...G.values()].filter(x=>!al||al.has(x.day))};
 const optsFor=(s,R)=>{const a=cands(s,R);return`<option value="">${a.length?'نقل إلى...':'لا يوجد جروب مطابق'}</option>`+a.map(x=>{const n=N[x.id]||0,f=n>=capOf(x);return`<option value="${x.id}" ${f&&!adm?'disabled':''}>${slotLb(x)} (${n}/${capOf(x)})${f?' • ممتلئ':''}</option>`}).join('')};
 const render=()=>{const R=rules();$('#rs').innerHTML=`<div class="card wrap"><h3>${mode=='all'?'نتائج البحث في كل النظام':'الطلاب الجدد'} (${cur.length})</h3><table class="table"><tr><th>الكود</th><th>الاسم</th><th>الكلية</th><th>الليفل</th><th>المستوى الدراسي</th><th>الجروب الحالي</th><th>نقل إلى</th><th></th></tr>${cur.slice(0,shown).map(s=>`<tr><td>${esc(s.code)}</td><td>${esc(s.name)}</td><td>${esc(s.college)}</td><td>${esc(s.level)}</td><td>${esc(s.study_level)}</td><td>${(E[s.code]||[]).map(i=>S[i]?slotLb(S[i]):'').join('<br>')||'—'}</td><td><select data-mv="${esc(s.code)}">${optsFor(s,R)}</select></td><td><button type="button" class="chip" data-ed="${esc(s.code)}">تعديل</button></td></tr>`).join('')||'<tr><td colspan="8">لا يوجد طلاب</td></tr>'}</table>${shown<cur.length?`<button class="btn alt" id="mo">عرض المزيد (${cur.length-shown})</button>`:''}</div>`;if($('#mo'))$('#mo').onclick=()=>{shown+=50;render()}};
 const refresh=()=>{const R=rules();document.querySelectorAll('[data-mv]').forEach(x=>{const s=cur.find(y=>y.code==x.dataset.mv);if(s)x.innerHTML=optsFor(s,R)})};
