// ===== دمج الجروبات المكررة (نفس اليوم والوقت والكلاس) =====
async function mergeDup(){
 const [sl,en]=await Promise.all([all('slots?select=*'),all('enrollments?select=slot_id')]),N={},G={};let n=0;
 en.forEach(e=>N[e.slot_id]=(N[e.slot_id]||0)+1);sl.forEach(s=>{const k=[s.day,fmt(s.start_time),fmt(s.end_time),nzp(s.place)].join('|');(G[k]=G[k]||[]).push(s)});
 for(const g of Object.values(G)){if(g.length<2)continue;g.sort((a,b)=>(N[b.id]||0)-(N[a.id]||0)||(b.lecturer_code?1:0)-(a.lecturer_code?1:0));const p=g[0],rest=g.slice(1),pa={};
  const lec=p.lecturer_code||rest.find(r=>r.lecturer_code)?.lecturer_code,lvl=p.level||rest.find(r=>r.level)?.level;if(lec&&!p.lecturer_code)pa.lecturer_code=lec;if(lvl&&!p.level)pa.level=lvl;if(Object.keys(pa).length)await api('slots?id=eq.'+p.id,'PATCH',pa);
  for(const r of rest){try{const E=await api(`enrollments?slot_id=eq.${r.id}&select=student_code`);if(E.length)await api('enrollments?on_conflict=student_code,slot_id','POST',E.map(e=>({student_code:e.student_code,slot_id:p.id})),'resolution=merge-duplicates,return=minimal');
   await api('attendance?slot_id=eq.'+r.id,'PATCH',{slot_id:p.id});await api('change_requests?from_slot=eq.'+r.id,'PATCH',{from_slot:p.id});await api('change_requests?to_slot=eq.'+r.id,'PATCH',{to_slot:p.id});await api('slots?id=eq.'+r.id,'DELETE');n++}catch(e){console.warn('تعذر دمج',r.id,e.message)}}}
 return n}

